CREATE TABLE t (a INT, b TEXT);
INSERT INTO t VALUES (1, 'x'), (NULL, 'y'), (30, 'z');
SELECT b, CASE WHEN a > 10 THEN 'big' WHEN a > 0 THEN 'small' ELSE 'none' END AS size FROM t ORDER BY b;

CREATE TABLE t (g TEXT, v INT);
INSERT INTO t VALUES ('a', 1), ('a', 5), ('b', 7);
SELECT g, SUM(CASE WHEN v > 3 THEN v ELSE 0 END) AS big FROM t GROUP BY g ORDER BY g;
